// Logs → Sessions tab — ONE ROW PER SESSION, its whole footprint, AS GRAPH SOURCE (epic #3604).
//
// The spine of the Logs workspace. Every other tab is one STREAM; this one is one SESSION across all
// of them: how many tools it ran, skills it invoked, MCP calls it made, coordination events it
// emitted, what it cost, and whether it is running, idle or waiting on a person. Those six facts live
// in five different logs plus the cost rollup and were reachable together from nowhere.
//
// Sorting is the whole interaction. "Which session is expensive", "which is silent", "which is stuck"
// are the same table ordered three ways, so the columns sort and nothing else is needed.
//
// A NOTE ON THE COST COLUMN, because a number on a screen is believed. The rollup can charge one
// transcript to two sessions when both panes point at it — measured at $260.81 of a $3,452.75 total,
// filed as `cost-double-counts-a-transcript-two-panes-share`. This tab renders what the rollup says;
// it does not silently correct it, and it does not pretend the total is exact.
//
// Preview note: the rollup type is app-internal (unresolvable in this sandbox), so it and a sample
// fleet are inlined. Every prop still overrides the sample when composed by LogsWorkspace.
import { StatTile } from "@/shared/ui/data/StatTile";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";

/** One session's footprint — the `logs::SessionRow` shape. `cost_usd` is snake_case ON THE WIRE. */
interface SessionRollupRow {
  session: string; role: string;
  tools: number; skills: number; mcp: number; coord: number;
  cost_usd: number; activity: string;
}

export type SessionSort = "activity" | "cost" | "traffic" | "name";

const SAMPLE_ROWS: SessionRollupRow[] = [
  { session: "studio-code:director", role: "director", tools: 412, skills: 3, mcp: 8, coord: 96, cost_usd: 184.21, activity: "run" },
  { session: "studio-code:mobile-tunnel", role: "worker", tools: 210, skills: 0, mcp: 0, coord: 12, cost_usd: 42.87, activity: "attn" },
  { session: "design-studio:designer-react", role: "worker", tools: 96, skills: 1, mcp: 2, coord: 4, cost_usd: 260.81, activity: "idle" },
  { session: "planning_alpha", role: "planner", tools: 18, skills: 0, mcp: 0, coord: 2, cost_usd: 3.4, activity: "" },
  { session: "cli-typer:persistence-store", role: "worker", tools: 0, skills: 0, mcp: 0, coord: 0, cost_usd: 0, activity: "" },
];

/** Everything a session did, in one number — the "is this session doing anything at all" test. */
export function sessionTraffic(r: SessionRollupRow): number {
  return r.tools + r.skills + r.mcp + r.coord;
}

/** A session that produced nothing and cost nothing. Kept out of the way rather than deleted: it is
 *  still a session that EXISTS, and hiding it outright would misreport the fleet's size. */
export function isDormant(r: SessionRollupRow): boolean {
  return sessionTraffic(r) === 0 && r.cost_usd === 0;
}

/** Sort, always with a stable tiebreak on the session id so equal rows do not shuffle between polls. */
export function sortSessions(rows: SessionRollupRow[], sort: SessionSort): SessionRollupRow[] {
  const byName = (a: SessionRollupRow, b: SessionRollupRow) => a.session.localeCompare(b.session);
  const rank: Record<string, number> = { attn: 0, run: 1, idle: 2, "": 3 };
  const copy = [...rows];
  if (sort === "name") return copy.sort(byName);
  if (sort === "cost") return copy.sort((a, b) => b.cost_usd - a.cost_usd || byName(a, b));
  if (sort === "traffic") return copy.sort((a, b) => sessionTraffic(b) - sessionTraffic(a) || byName(a, b));
  // activity: what needs a person first, then what is running, then idle, then never-reported.
  return copy.sort((a, b) => (rank[a.activity] ?? 3) - (rank[b.activity] ?? 3) || byName(a, b));
}

/** Fleet totals. Cost is summed as reported — see the note at the top of this file. */
export function sessionTotals(rows: SessionRollupRow[]) {
  return {
    sessions: rows.length,
    active: rows.filter((r) => !isDormant(r)).length,
    attn: rows.filter((r) => r.activity === "attn").length,
    cost: rows.reduce((n, r) => n + r.cost_usd, 0),
  };
}

/** `$1,234.56`, or `$0.00` — never `$NaN`, and never a bare number that could be read as a count. */
export function fmtUsd(n: number): string {
  const v = Number.isFinite(n) ? n : 0;
  return "$" + v.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

const ACTIVITY: Record<string, { label: string; color: string }> = {
  attn: { label: "waiting", color: "var(--danger)" },
  run: { label: "running", color: "var(--state-run, var(--success))" },
  idle: { label: "idle", color: "var(--fg-dim)" },
};
/** An unreported activity is NOT the same as idle — the session never said. Saying "idle" would be
 *  a claim the log does not support. */
const UNREPORTED = { label: "not reported", color: "var(--fg-dim)" };

const ROLE_COLOR: Record<string, string> = {
  director: "var(--accent)",
  planner: "var(--info, var(--accent))",
  worker: "var(--state-run, var(--success))",
  session: "var(--fg-dim)",
};

export interface SessionsTabProps {
  rows?: SessionRollupRow[];
  sort?: SessionSort;
  setSort?: (s: SessionSort) => void;
  /** Hide sessions with no traffic and no cost. */
  hideDormant?: boolean;
  setHideDormant?: (v: boolean) => void;
  /** First poll has returned — separates "still reading" from "genuinely empty". */
  loaded?: boolean;
}

export function SessionsTab({
  rows = SAMPLE_ROWS, sort = "activity", setSort = () => {},
  hideDormant = false, setHideDormant = () => {}, loaded = true,
}: SessionsTabProps) {
  const totals = sessionTotals(rows);
  const dormant = rows.length - totals.active;
  const shown = sortSessions(hideDormant ? rows.filter((r) => !isDormant(r)) : rows, sort);

  const chip = (k: SessionSort, label: string) => {
    const on = sort === k;
    return (
      <Box as="span" key={k} onClick={() => setSort(k)} style={{
        display: "inline-flex", alignItems: "center", padding: "4px 10px", borderRadius: 999, cursor: "pointer", fontSize: 11,
        border: on ? "1px solid var(--accent)" : "1px solid var(--border-soft)", background: on ? "var(--bg-elev2)" : "transparent", color: on ? "var(--fg)" : "var(--fg-muted)",
      }}>{label}</Box>
    );
  };

  const COLS = "1.7fr 86px 104px 60px 56px 52px 60px 88px";
  return (
    <Box style={{ display: "flex", flexDirection: "column", width: "100%" }}>
      <Box style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(130px, 1fr))", gap: 10, marginBottom: 14 }}>
        <StatTile k="sessions" v={totals.sessions} sub={dormant > 0 ? dormant + " with no activity" : "all have activity"} />
        <StatTile k="active" v={totals.active} sub="ran or cost something" />
        <StatTile k="waiting" v={totals.attn} tone={totals.attn > 0 ? "danger" : undefined} sub="stopped for a person" />
        <StatTile k="cost" v={fmtUsd(totals.cost)} tone="accent" sub="as the rollup reports it" />
      </Box>

      <Row align="center" gap={10} wrap style={{ marginBottom: 12 }}>
        <Text as="span" mono size={10} tone="dim" style={{ textTransform: "uppercase", letterSpacing: ".05em" }}>sort</Text>
        <Row gap={6} align="stretch">
          {chip("activity", "by activity")}
          {chip("cost", "by cost")}
          {chip("traffic", "by traffic")}
          {chip("name", "by name")}
        </Row>
        {dormant > 0 && (
          <Box as="span" onClick={() => setHideDormant(!hideDormant)} style={{
            display: "inline-flex", alignItems: "center", gap: 6, marginLeft: 8, padding: "4px 10px", borderRadius: 999, cursor: "pointer", fontSize: 11,
            border: hideDormant ? "1px solid var(--accent)" : "1px solid var(--border-soft)", background: hideDormant ? "var(--bg-elev2)" : "transparent", color: hideDormant ? "var(--fg)" : "var(--fg-muted)",
          }}>{hideDormant ? "showing active only" : "hide " + dormant + " with no activity"}</Box>
        )}
        <Box style={{ flex: 1 }} />
        <Text as="span" mono size={10} tone="dim">{shown.length} of {rows.length}</Text>
      </Row>

      {rows.length === 0 ? (
        <EmptyState
          iconVariant="dashed" icon="◻" size="sm"
          title={loaded ? "No sessions recorded" : "Reading the logs…"}
          description="A session appears here as soon as it runs a tool, invokes a skill, calls an MCP server, emits a coordination event, or reports a cost."
        />
      ) : (
        <Box border="soft" radius={7} style={{ overflow: "hidden" }}>
          <Box style={{ display: "grid", gridTemplateColumns: COLS, gap: 10, padding: "7px 12px", background: "var(--bg-elev2)", borderBottom: "1px solid var(--border-soft)", fontSize: 9.5, color: "var(--fg-dim)", textTransform: "uppercase", letterSpacing: ".05em" }}>
            <Box as="span">session</Box><Box as="span">role</Box><Box as="span">activity</Box>
            <Box as="span" style={{ textAlign: "right" }}>tools</Box>
            <Box as="span" style={{ textAlign: "right" }}>skills</Box>
            <Box as="span" style={{ textAlign: "right" }}>mcp</Box>
            <Box as="span" style={{ textAlign: "right" }}>coord</Box>
            <Box as="span" style={{ textAlign: "right" }}>cost</Box>
          </Box>
          {shown.map((r, i) => {
            const act = ACTIVITY[r.activity] ?? UNREPORTED;
            const dim = isDormant(r);
            return (
              <Box key={r.session} style={{ display: "grid", gridTemplateColumns: COLS, gap: 10, alignItems: "center", padding: "8px 12px", fontSize: 11, background: i % 2 ? "var(--bg-panel)" : "var(--bg-elev)", opacity: dim ? 0.55 : 1 }}>
                <Text as="span" mono size={11} style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{r.session}</Text>
                <Box as="span" style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
                  <Box as="span" bg={ROLE_COLOR[r.role] ?? "var(--fg-dim)"} radius={99} style={{ width: 6, height: 6 }} />
                  <Text as="span" mono size={10.5} tone="muted">{r.role}</Text>
                </Box>
                <Text as="span" mono size={10.5} style={{ color: act.color }}>{act.label}</Text>
                {/* A zero is rendered as a dash: in a table of counts, "0" and "—" read differently and
                    the dash makes a silent session visible at a glance down the column. */}
                <Text as="span" mono size={11} tone={r.tools ? "muted" : "dim"} style={{ textAlign: "right" }}>{r.tools || "—"}</Text>
                <Text as="span" mono size={11} tone={r.skills ? "muted" : "dim"} style={{ textAlign: "right" }}>{r.skills || "—"}</Text>
                <Text as="span" mono size={11} tone={r.mcp ? "muted" : "dim"} style={{ textAlign: "right" }}>{r.mcp || "—"}</Text>
                <Text as="span" mono size={11} tone={r.coord ? "muted" : "dim"} style={{ textAlign: "right" }}>{r.coord || "—"}</Text>
                <Text as="span" mono size={11} tone={r.cost_usd ? "muted" : "dim"} style={{ textAlign: "right" }}>{r.cost_usd ? fmtUsd(r.cost_usd) : "—"}</Text>
              </Box>
            );
          })}
        </Box>
      )}
    </Box>
  );
}

