// The Logs → Sessions tab — one row per session, its whole footprint.
//
// Carried ON the record, so it runs against the copy that actually mounts.
import { describe, it, expect, vi } from "vitest";
import { render, screen, fireEvent } from "@testing-library/react";
import {
  SessionsTab, sessionTraffic, isDormant, sortSessions, sessionTotals, fmtUsd,
} from "./SessionsTab";

const ROWS = [
  { session: "b:idle", role: "worker", tools: 5, skills: 0, mcp: 0, coord: 0, cost_usd: 1.5, activity: "idle" },
  { session: "a:stuck", role: "worker", tools: 2, skills: 0, mcp: 0, coord: 1, cost_usd: 0.25, activity: "attn" },
  { session: "c:run", role: "director", tools: 100, skills: 4, mcp: 2, coord: 30, cost_usd: 50, activity: "run" },
  { session: "d:quiet", role: "planner", tools: 0, skills: 0, mcp: 0, coord: 0, cost_usd: 0, activity: "" },
];

describe("pure helpers", () => {
  it("sessionTraffic sums every stream, not just tools", () => {
    expect(sessionTraffic(ROWS[2])).toBe(136);
    expect(sessionTraffic(ROWS[3])).toBe(0);
  });

  it("isDormant needs BOTH no traffic and no cost", () => {
    // Cost with no traffic still means the session ran — the transcript is evidence.
    expect(isDormant(ROWS[3])).toBe(true);
    expect(isDormant({ ...ROWS[3], cost_usd: 0.01 })).toBe(false);
    expect(isDormant({ ...ROWS[3], coord: 1 })).toBe(false);
  });

  it("sorts by activity with WAITING first — the only one that needs a person", () => {
    expect(sortSessions(ROWS, "activity").map((r) => r.session))
      .toEqual(["a:stuck", "c:run", "b:idle", "d:quiet"]);
  });

  it("sorts by cost and by traffic, descending", () => {
    expect(sortSessions(ROWS, "cost").map((r) => r.session)[0]).toBe("c:run");
    expect(sortSessions(ROWS, "traffic").map((r) => r.session)[0]).toBe("c:run");
  });

  it("breaks ties on the session id, so equal rows do not shuffle between polls", () => {
    // Without a stable tiebreak the table reorders itself every 5s and is unreadable.
    const tied = [
      { session: "z", role: "worker", tools: 0, skills: 0, mcp: 0, coord: 0, cost_usd: 7, activity: "run" },
      { session: "a", role: "worker", tools: 0, skills: 0, mcp: 0, coord: 0, cost_usd: 7, activity: "run" },
      { session: "m", role: "worker", tools: 0, skills: 0, mcp: 0, coord: 0, cost_usd: 7, activity: "run" },
    ];
    expect(sortSessions(tied, "cost").map((r) => r.session)).toEqual(["a", "m", "z"]);
    expect(sortSessions(tied, "activity").map((r) => r.session)).toEqual(["a", "m", "z"]);
  });

  it("never mutates the input array", () => {
    // The rows come straight from a poll's state; sorting in place would mutate React state.
    const before = ROWS.map((r) => r.session);
    sortSessions(ROWS, "cost");
    expect(ROWS.map((r) => r.session)).toEqual(before);
  });

  it("ranks an UNREPORTED activity last, not as idle", () => {
    const rows = [{ session: "x", role: "worker", tools: 0, skills: 0, mcp: 0, coord: 0, cost_usd: 0, activity: "invented" }];
    expect(sortSessions([...ROWS, ...rows], "activity").at(-1)!.session).toBe("x");
  });

  it("sessionTotals counts active rather than total, and sums cost as reported", () => {
    expect(sessionTotals(ROWS)).toEqual({ sessions: 4, active: 3, attn: 1, cost: 51.75 });
  });

  it("fmtUsd always renders money, never NaN", () => {
    // A missing wire field arrives as undefined; `$NaN` on a cost column is worse than `$0.00`
    // because it looks like a UI crash rather than a value.
    expect(fmtUsd(0)).toBe("$0.00");
    expect(fmtUsd(1234.5)).toContain("1,234.50");
    expect(fmtUsd(NaN)).toBe("$0.00");
    expect(fmtUsd(undefined as unknown as number)).toBe("$0.00");
  });
});

describe("SessionsTab", () => {
  it("renders every session with its per-stream counts", () => {
    render(<SessionsTab rows={ROWS} />);
    expect(screen.getByText("c:run")).toBeInTheDocument();
    expect(screen.getByText("100")).toBeInTheDocument(); // tools
    expect(screen.getByText("$50.00")).toBeInTheDocument();
  });

  it("shows a zero as a dash, so a silent session is visible down the column", () => {
    render(<SessionsTab rows={[ROWS[3]]} />);
    // four count columns + cost, all zero
    expect(screen.getAllByText("—")).toHaveLength(5);
  });

  it("does not call an UNREPORTED activity idle", () => {
    // The log never said; "idle" would be a claim it does not support.
    render(<SessionsTab rows={[ROWS[3]]} />);
    expect(screen.getByText("not reported")).toBeInTheDocument();
    expect(screen.queryByText("idle")).toBeNull();
  });

  it("counts dormant sessions but keeps them in the fleet total", () => {
    // Hiding them outright would misreport how many sessions exist.
    render(<SessionsTab rows={ROWS} />);
    expect(screen.getByText("1 with no activity")).toBeInTheDocument();
    expect(screen.getByText("4 of 4")).toBeInTheDocument();
  });

  it("can hide the dormant ones, and says so", () => {
    const setHide = vi.fn();
    render(<SessionsTab rows={ROWS} setHideDormant={setHide} />);
    fireEvent.click(screen.getByText("hide 1 with no activity"));
    expect(setHide).toHaveBeenCalledWith(true);
  });

  it("hiding them changes the shown count but not the fleet count", () => {
    render(<SessionsTab rows={ROWS} hideDormant />);
    expect(screen.getByText("3 of 4")).toBeInTheDocument();
    expect(screen.queryByText("d:quiet")).toBeNull();
  });

  it("reports the sort choice instead of sorting internally", () => {
    const setSort = vi.fn();
    render(<SessionsTab rows={ROWS} setSort={setSort} />);
    fireEvent.click(screen.getByText("by cost"));
    expect(setSort).toHaveBeenCalledWith("cost");
  });

  it("an empty store is an empty STATE, and loading says loading", () => {
    const { rerender } = render(<SessionsTab rows={[]} loaded />);
    expect(screen.getByText("No sessions recorded")).toBeInTheDocument();
    rerender(<SessionsTab rows={[]} loaded={false} />);
    expect(screen.getByText("Reading the logs…")).toBeInTheDocument();
  });
});
